import p from"color-space/lchuv.js";import s from"color-rgba";import h from"color-space/rgb.js";import a from"color-space/xyz.js";import{clamp as u}from"./math.js";export function asString(t){return typeof t=="string"?t:toString(t)}const c=1024,i={};let f=0;export function withAlpha(t){if(t.length===4)return t;const r=t.slice();return r[3]=1,r}export function rgbaToLcha(t){const r=a.lchuv(h.xyz(t));return r[3]=t[3],r}export function lchaToRgba(t){const r=a.rgb(p.xyz(t));return r[3]=t[3],r}export function fromString(t){if(i.hasOwnProperty(t))return i[t];if(f>=c){let n=0;for(const e in i)(n++&3)===0&&(delete i[e],--f)}const r=s(t);if(r.length!==4)throw new Error('Failed to parse "'+t+'" as color');for(const n of r)if(isNaN(n))throw new Error('Failed to parse "'+t+'" as color');return normalize(r),i[t]=r,++f,r}export function asArray(t){return Array.isArray(t)?t:fromString(t)}export function normalize(t){return t[0]=u(t[0]+.5|0,0,255),t[1]=u(t[1]+.5|0,0,255),t[2]=u(t[2]+.5|0,0,255),t[3]=u(t[3],0,1),t}export function toString(t){let r=t[0];r!=(r|0)&&(r=r+.5|0);let n=t[1];n!=(n|0)&&(n=n+.5|0);let e=t[2];e!=(e|0)&&(e=e+.5|0);const o=t[3]===void 0?1:Math.round(t[3]*1e3)/1e3;return"rgba("+r+","+n+","+e+","+o+")"}export function isStringColor(t){try{return fromString(t),!0}catch{return!1}}
